// convertJSONNumbers recursively walks a value decoded with json.UseNumber()
// and converts json.Number back to int64 or float64 so YAML marshals them
// as plain numbers instead of quoted strings.
func convertJSONNumbers(v any) any {
	switch val := v.(type) {
	case json.Number:
		if i, err := val.Int64(); err == nil {
			return i
		}
		if f, err := val.Float64(); err == nil {
			return f
		}
		return val.String()
	case map[string]any:
		for k, v2 := range val {
			val[k] = convertJSONNumbers(v2)
		}
		return val
	case []any:
		for i, v2 := range val {
			val[i] = convertJSONNumbers(v2)
		}
		return val
	default:
		return v
	}
}

